import math

def predict(probe):
    # Mechanism:
    # - For |x| > 4.35: output 0 [E1,E3,E5,E6,E7,E9,E11,E13,E15,E17,E18]
    # - For 0 < x <= 4.35: output ceil(x) [E2,E4,E14,E16]
    # - For -4.35 <= x <= 0: output trunc toward zero [E2,E4,E14,E16]
    # - Boundary 4.35 inclusive on both sides [E14,E18]
    ys = []
    for x in probe["x"]:
        if x is None:
            ys.append(None)
            continue
        try:
            x = float(x)
        except Exception:
            ys.append(None)
            continue
        if x > 4.35 or x < -4.35:
            ys.append(0.0)
        elif x > 0:
            ys.append(float(math.ceil(x)))
        else:
            ys.append(float(math.trunc(x)))
    return {"y": ys}
